/*
  标准四层BOM演示数据
  分类树收敛为：成品 / 半成品 / 原材料与标准件
  BOM层级为：成品 -> 功能总成 -> 子组件 -> 基础件
*/

SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;
USE `ruoyi-vue-pro`;

START TRANSACTION;

DELETE FROM `erp_bom_item` WHERE `id` BETWEEN 961300 AND 961399 OR `id` BETWEEN 972900 AND 973399;
DELETE FROM `erp_bom` WHERE `id` BETWEEN 961200 AND 961219 OR `id` BETWEEN 972500 AND 972899;
DELETE FROM `erp_product` WHERE `id` BETWEEN 961001 AND 961030 OR `id` BETWEEN 972000 AND 972499;
DELETE FROM `erp_product_category` WHERE (`id` BETWEEN 961010 AND 961019) OR (`id` BETWEEN 972010 AND 973099);
DELETE FROM `erp_product_unit` WHERE `id` IN (961020, 972020);







COMMIT;

SET FOREIGN_KEY_CHECKS = 1;
